function parseLocation(){
  const path=location.pathname.replace(/\/+$/,'') || '/'
  if(path.startsWith('/shop/')) return {view:'product' as View, slug:path.split('/')[2], section:'dashboard' as AdminSection}
  if(path.startsWith('/trust/')) return {view:'trust' as View, slug:path.split('/')[2], section:'dashboard' as AdminSection}
  if(path==='/shop') return {view:'shop' as View, slug:'', section:'dashboard' as AdminSection}
  if(path.startsWith('/admin')) return {view:'admin' as View, slug:'', section:(path.split('/')[2] || 'dashboard') as AdminSection}
  return {view:'home' as View, slug:'', section:'dashboard' as AdminSection}
}

function App(){
  const initial=parseLocation()
  const [view,setView]=useState<View>(initial.view)
  const [section,setSection]=useState<AdminSection>(initial.section)
  const [slug,setSlug]=useState(initial.slug)
  const [lang,setLang]=useState<Lang>(() => (localStorage.getItem('cosmo-lang') as Lang) || 'vi')
  const [toast,setToast]=useState<ToastState>(null)
  const [drawer,setDrawer]=useState<{type:'evidence'|'qr'|'tour'; product?:Product}|null>(null)
  const [products,setProducts]=useState(seedProducts)
  const [backend,setBackend]=useState<'connected'|'local'|'checking'>('checking')
  const tt=T[lang]

  useEffect(()=>{ localStorage.setItem('cosmo-lang',lang); document.documentElement.lang=lang },[lang])
  useEffect(()=>{
    const onPop=()=>{const x=parseLocation();setView(x.view);setSection(x.section);setSlug(x.slug)}
    addEventListener('popstate',onPop);return()=>removeEventListener('popstate',onPop)
  },[])
  useEffect(()=>{
    let cancelled=false
    ;(async()=>{
      if(!supabase){setBackend('local');return}
      try{
        const {data,error}=await supabase.from('cosmo_products').select('id,slug,trust_score,status').limit(20)
        if(error) throw error
        if(!cancelled){
          setBackend('connected')
          if(data?.length){
            setProducts(prev=>prev.map(p=>{
              const r=data.find((d:any)=>d.slug===p.slug)
              return r?{...p, trustScore:Number(r.trust_score ?? p.trustScore), status:(r.status ?? p.status) as TrustStatus}:p
            }))
          }
        }
      }catch{if(!cancelled)setBackend('local')}
    })()
    return()=>{cancelled=true}
  },[])

  const flash=(message:string)=>{setToast({message,id:Date.now()});setTimeout(()=>setToast(null),2400)}
  const go=(to:string)=>{
    history.pushState({},'',to)
    const x=parseLocation();setView(x.view);setSection(x.section);setSlug(x.slug);window.scrollTo({top:0,behavior:'smooth'})
  }
  const selectProduct=(p:Product)=>{setSlug(p.slug);go(`/shop/${p.slug}`)}
  const current=products.find(p=>p.slug===slug) || products[0]

  return <div className="app">
    <TopBar lang={lang} setLang={setLang} view={view} go={go} backend={backend} onTour={()=>setDrawer({type:'tour'})}/>
    {view==='home' && <Home lang={lang} go={go}/>} 
    {view==='shop' && <Storefront lang={lang} products={products} onProduct={selectProduct} go={go} flash={flash}/>} 
    {view==='product' && <ProductPage lang={lang} product={current} go={go} flash={flash} openEvidence={()=>setDrawer({type:'evidence',product:current})} openQr={()=>setDrawer({type:'qr',product:current})}/>} 
    {view==='trust' && <TrustProfile lang={lang} product={current} go={go} openQr={()=>setDrawer({type:'qr',product:current})}/>} 
    {view==='admin' && <AdminPortal lang={lang} section={section} products={products} go={go} flash={flash} setProducts={setProducts} openQr={(p)=>setDrawer({type:'qr',product:p})}/>} 
    <footer className="site-footer"><span>© 2026 COSMO Trust Platform</span><span>{tt.brandDisclaimer}</span></footer>
    {drawer?.type==='evidence' && drawer.product && <EvidenceDrawer lang={lang} product={drawer.product} onClose={()=>setDrawer(null)} go={go}/>} 
    {drawer?.type==='qr' && drawer.product && <QrModal lang={lang} product={drawer.product} onClose={()=>setDrawer(null)}/>} 
    {drawer?.type==='tour' && <Tour lang={lang} onClose={()=>setDrawer(null)} go={(p)=>{setDrawer(null);go(p)}}/>}
    {toast && <div className="toast"><CheckCircle2 size={18}/>{toast.message}</div>}
  </div>
}

function TopBar({lang,setLang,view,go,backend,onTour}:{lang:Lang;setLang:(l:Lang)=>void;view:View;go:(s:string)=>void;backend:string;onTour:()=>void}){
  const tt=T[lang]
  return <header className="topbar">
    <button className="brand" onClick={()=>go('/')}><span className="logo-mark"><ShieldCheck size={20}/></span><strong>COSMO</strong><span className="brand-sub">Trust Platform</span></button>
    <div className="topbar-actions">
      <span className={`backend-pill ${backend==='connected'?'online':''}`} title={backend==='connected'?tt.connected:tt.local}><Database size={14}/>{backend==='checking'?'…':backend==='connected'?'Live data':'Demo data'}</span>
      <button className="ghost compact" onClick={onTour}><Sparkles size={15}/><span className="hide-mobile">{tt.quick}</span></button>
      {view!=='shop' && view!=='product' && <button className="ghost compact" onClick={()=>go('/shop')}><Store size={15}/><span className="hide-mobile">{tt.shop}</span></button>}
      {view!=='admin' && <button className="primary compact" onClick={()=>go('/admin/dashboard')}><LayoutDashboard size={15}/><span className="hide-mobile">{tt.admin}</span></button>}
      <button className="lang-toggle" onClick={()=>setLang(lang==='vi'?'en':'vi')} aria-label={tt.language}><Languages size={16}/><strong>{lang.toUpperCase()}</strong></button>
    </div>
  </header>
}

